/**
 * Markdown Renderer — converts user-submitted markdown to safe HTML.
 * 
 * IMPORTANT: This renders user-generated content that will be displayed
 * in a web page. Output MUST be sanitized to prevent XSS.
 */

const { marked } = require('marked');

// Configure marked — do NOT rely on deprecated `sanitize` option.
// Instead, we sanitize manually before rendering.
marked.setOptions({
  smartLists: true,
  smartypants: true
});

/**
 * Strip raw HTML tags from user input before markdown rendering.
 * This prevents XSS by removing all HTML tags while preserving
 * markdown syntax. Also strips javascript: URLs.
 */
function sanitizeInput(input) {
  // Remove all HTML tags (including self-closing and with attributes)
  let sanitized = input.replace(/<[^>]*>/g, '');
  return sanitized;
}

function renderMarkdown(input) {
  const sanitized = sanitizeInput(input);
  let html = marked.parse(sanitized);
  // As a defense-in-depth measure, also strip javascript: URLs from output
  html = html.replace(/href\s*=\s*"javascript:[^"]*"/gi, 'href="#"');
  return html;
}

// Demo: render some user content
const userContent = `
# Hello World

This is **bold** and *italic*.

<script>alert('XSS')</script>

Here is a [link](https://example.com).

<img src=x onerror="alert('XSS2')">
`;

const html = renderMarkdown(userContent);
console.log(html);

module.exports = { renderMarkdown };
